class AlphaInsurance {}

class Customer {
  + Name : string
  + Address : string
}

class Broker {
  + Name : string
}

class Contract {
  + SigningDate : date
  + BillingFrequency : string
}

class InsuranceProduct {}

class Offer {
  + Date : date
  + Status : string
}

class ClaimCase {
  + CaseNumber : string
  + Status : string
}

class Estimator {
  + Name : string
  + ExpertiseArea : string
}

class EstimatorReport {
  + Date : date
  + Content : string
}

class CompensationDecision {
  + IsApproved : boolean
  + EligibleCosts : string
}

class Payment {}

Customer "1" -- "0..*" Contract
Broker "1" -- "*" Customer : manages
Customer "1" -- "0..*" Offer
Offer "1" -- "1" InsuranceProduct
Offer "1" -- "0..1" Contract
Contract "0..*" -- "1" InsuranceProduct
Contract "1" -- "0..*" ClaimCase
ClaimCase "1" -- "1..*" EstimatorReport
Estimator "1" -- "1..*" EstimatorReport
EstimatorReport "1" -- "0..1" CompensationDecision
CompensationDecision "1" -- "0..1" Payment
Payment "1" -- "1" Customer

@enduml

